y: O(n)\r\n    * Tags:\r\n    *     DS: hash map\r\n    *     A: top-down\r\n    * @param {number[]} nums\r\n    * @return {boolean}\r\n    */\r\n   validPartition(nums) {\r\n      const memo = new Map([[nums.length, true]]);\r\n\r\n      const dfs = (index) => {\r\n         if (memo.has(index)) {\r\n            return memo.get(index)\r\n         } else if (index > nums.length) {\r\n            return false\r\n         }\r\n\r\n         memo.set(index, false);\r\n         // two digits equals\r\n         if (index + 1 < nums.length &&\r\n            nums[index] === nums[index + 1] &&\r\n            dfs(index + 2)\r\n         ) {\r\n            memo.set(index, true);\r\n            // three digits equals\r\n         } else if (\r\n            index + 2 < nums.length &&\r\n            nums[index] === nums[index + 1] &&\r\n            nums[index + 1] === nums[index + 2] &&\r\n            dfs(index + 3)\r\n         ) {\r\n            memo.set(index, true);\r\n            // three digits increasing by one\r\n         } else if (\r\n            index + 2 < nums.length &&\r\n            nums[index] + 2 === nums[index + 1] + 1 &&\r\n            nums[index + 1] + 1 === nums[index + 2] &&\r\n            dfs(index + 3)\r\n         ) {\r\n            memo.set(index, true);\r\n         }\r\n         return memo.get(index)\r\n      }\r\n      return dfs(0)\r\n   };\r\n\r\n   /**\r\n    * Time complexity: O(n)\r\n    * Auxiliary space complexity: O(n)\r\n    * Tags:\r\n    *     DS: array\r\n    *     A: bottom-up\r\n    * @param {number[]} nums\r\n    * @return {boolean}\r\n    */\r\n   validPartition(nums) {\r\n      const cache = Array(nums.length + 1).fill(false);\r\n      cache[cache.length - 1] = true;\r\n\r\n      for (let index = nums.length - 1; index > -1; index--) {\r\n         // two digits equals\r\n         if (\r\n            index + 1 < nums.length &&\r\n            nums[index] === nums[index + 1] &&\r\n            cache[index + 2]\r\n         ) {\r\n            cache[index] = true;\r\n            // three digits equals\r\n         } else if (\r\n            index + 2 < nums.length &&\r\n            nums[index] === nums[index + 1] &&\r\n            nums[index + 1] === nums[index + 2] &&\r\n            cache[index + 3]\r\n         ) {\r\n            cache[index] = true;\r\n            // three digits increasing by one\r\n         } else if (\r\n            index + 2 < nums.length &&\r\n            nums[index] + 2 === nums[index + 1] + 1 &&\r\n            nums[index + 1] + 1 === nums[index + 2] &&\r\n            cache[index + 3]\r\n         ) {\r\n            cache[index] = true;\r\n         }\r\n      }\r\n      return cache[0]\r\n   };\r\n\r\n   /**\r\n    * Time complexity: O(n)\r\n    * Auxiliary space complexity: O(1)\r\n    * Tags:\r\n    *     DS: array\r\n    *     A: bottom-up\r\n    * @param {number[]} nums\r\n    * @return {boolean}\r\n    */\r\n   validPartition(nums) {\r\n      const cache = [true, true, true];\r\n\r\n      for (let index = nums.length - 1; index > -1; index--) {\r\n         let cache0 = false;\r\n         // two digits equals\r\n         if (\r\n            index + 1 < nums.length &&\r\n            nums[index] === nums[index + 1] &&\r\n            cache[1]\r\n         ) {\r\n            cache0 = true;\r\n            // three digits equals\r\n         } else if (\r\n            index + 2 < nums.length &&\r\n            nums[index] === nums[index + 1] &&\r\n            nums[index + 1] === nums[index + 2] &&\r\n            cache[2]\r\n         ) {\r\n            cache0 = true;\r\n            // three digits increasing by one\r\n         } else if (\r\n            index + 2 < nums.length &&\r\n            nums[index] + 2 === nums[index + 1] + 1 &&\r\n            nums[index + 1] + 1 === nums[index + 2] &&\r\n            cache[2]\r\n         ) {\r\n            cache0 = true;\r\n         }\r\n         cache[2] = cache[1];\r\n         cache[1] = cache[0];\r\n         cache[0] = cache0;\r\n      }\r\n      return cache[0]\r\n   };\r\n}\r\n\r\n\r\nconst validPartition = new Solution().validPartition;','console.log(new Solution().validPartition([4, 4, 4, 5, 6]) === true)\r\nconsole.log(new Solution().validPartition([1, 1, 1, 2]) === false)\r\nconsole.log(new Solution().validPartition([993335, 993336, 993337, 993338, 993339, 993340, 993341]) === false)\r\nconsole.log(new Solution().validPartition([803201, 803201, 803201, 803201, 803202, 803203]) === true)\r\nconsole.log(new Solution().validPartition([67149, 67149, 67149, 67149, 67149, 136768, 136768, 136768, 136768, 136768, 136768, 136768, 136769, 136770, 136771, 136772, 136773, 136774, 136775, 136776, 136777, 136778, 136779, 136780, 136781, 136782, 136783, 136784]) === false)\r\nconsole.log(new Solution().validPartition([7096, 7096, 7096, 7096, 7097, 7098, 7098, 7098, 7098, 7098, 7099, 7100, 7101, 7102, 7103, 7104, 7104, 7105, 7105, 7105, 7106, 7106, 7106, 7107, 7107, 7107, 7108, 7109, 7110, 7111, 7112, 7113, 7113, 7113, 7114, 7114, 7114, 7115, 7115, 7115, 7116, 7116, 7116, 7116, 7116, 7116, 7117, 7117, 7117, 7118, 7119, 7120, 7120, 7120, 7121, 7122, 7123, 7124, 7124, 7125, 7125, 7125, 7126, 7126, 7126, 7126, 7126, 7127, 7128, 7129, 7129, 7130, 7131, 7131, 7131, 7131, 7132, 7133, 7134, 7134, 7134, 7135, 7136, 7137, 7137, 7138, 7139, 7140, 7140, 7140, 7140, 7140, 7141, 7142, 7143, 7143, 7144, 7145, 7145, 7145, 7145, 7146, 7146, 7147, 7147, 7147, 7147, 7147, 7147, 7148, 7149, 7149, 7149, 7150, 7150, 7150, 7150, 7150, 7151, 7151, 7151, 7151, 7152, 7153, 7153, 7154, 7155, 7156, 7156, 7156, 7157, 7158, 7158, 7158, 7159, 7160, 7161, 7162, 7162, 7163, 7163, 7163, 7164, 7165, 7165, 7166, 7167, 7167, 7167, 7168, 7168, 7168, 7169, 7169, 7169, 7169, 7169, 7169, 7169, 7170, 7171, 7171, 7171, 7171, 7172, 7173, 7174, 7174, 7175, 7176, 7177, 7178, 7179, 7180, 7180, 7181, 7181, 7181, 7181, 7181, 7181, 7181, 7181, 7182, 7183, 7183, 7183, 7183, 7184, 7184, 7184, 7184, 7185, 7186, 7187, 7187, 7187, 7188, 7188, 7188, 7189, 7190, 7190, 719