Person);\r\n\r\n\r\n      while (index < M) {\r\n         const currPeople = new Set();\r\n         const timeStamp = meetings[index][2];\r\n\r\n         while (index < M && timeStamp == meetings[index][2]) {\r\n            const [u, v,] = meetings[index];\r\n            dsu.union(u, v);\r\n            currPeople.add(u);\r\n            currPeople.add(v);\r\n            index++;\r\n         }\r\n\r\n         for (const person of currPeople) {\r\n            if (dsu.find(person) !== dsu.find(0)) {\r\n               dsu.reset(person);\r\n            }\r\n         }\r\n      }\r\n\r\n      const res = [];\r\n\r\n      for (let person = 0; person < n; person++) {\r\n         if (dsu.parent[person] === dsu.parent[0]) {\r\n            res.push(person);\r\n         }\r\n      }\r\n\r\n      return res\r\n   };\r\n}\r\n\r\n\r\nconst findAllPeople = new Solution().findAllPeople;','console.log(new Solution().findAllPeople(4, [[3, 1, 3], [1, 2, 2], [0, 3, 3]], 3).toString() === [0, 1, 3].toString())\r\nconsole.log(new Solution().findAllPeople(6, [[1, 2, 5], [2, 3, 8], [1, 5, 10]], 1).toString() === [0, 1, 2, 3, 5].toString())\r\nconsole.log(new Solution().findAllPeople(5, [[3, 4, 2], [1, 2, 1], [2, 3, 1]], 1).toString() === [0, 1, 2, 3, 4].toString())\r\nconsole.log(new Solution().findAllPeople(5, [[1, 4, 3], [0, 4, 3]], 3).toString() === [0, 1, 3, 4].toString())\r\nconsole.log(new Solution().findAllPeople(135, [[26, 7, 481], [28, 120, 80], [87, 71, 36], [11, 86, 164], [87, 32, 4], [8, 104, 240], [110, 6, 27], [120, 126, 209], [5, 67, 220], [61, 47, 175], [60, 52, 86], [88, 53, 453], [40, 124, 206], [122, 22, 62], [4, 26, 433], [46, 56, 214], [15, 6, 264], [128, 31, 313], [24, 20, 393], [7, 20, 282], [65, 84, 216], [55, 132, 241], [50, 32, 338], [61, 69, 459], [130, 2, 53], [43, 106, 322], [61, 51, 99], [43, 61, 64], [34, 37, 474], [94, 116, 338], [19, 133, 277], [82, 40, 148], [124, 129, 496], [73, 82, 417], [7, 6, 416], [61, 15, 98], [92, 45, 293], [78, 109, 130], [120, 9, 18