    */\r\n   shortestDistanceAfterQueries(n, queries) {\r\n      const nexts = Array.from({ length: n - 1 }, (_, index) => [index + 1])\r\n      const res = []\r\n\r\n      const bfs = () => {\r\n         // queue([(city, distance), ...])\r\n         const queue = new Queue([[0, 0]]);\r\n         let visited = Array(n).fill(false);\r\n         visited[0] = true\r\n\r\n         while (queue.size()) {\r\n            const [city, dist] = queue.dequeue();\r\n\r\n            if (city === n - 1) {\r\n               res.push(dist);\r\n               return\r\n            }\r\n\r\n            for (const nextCity of nexts[city]) {\r\n               if (visited[nextCity] === false) {\r\n                  queue.push([nextCity, dist + 1]);\r\n                  visited[nextCity] = true;\r\n               }\r\n            }\r\n         }\r\n      }\r\n\r\n      for (const [src, dst] of queries) {\r\n         nexts[src].push(dst);\r\n         bfs()\r\n      }\r\n\r\n      return res\r\n   };\r\n}\r\n\r\n\r\nconst shortestDistanceAfterQueries = new Solution().shortestDistanceAfterQueries;','console.log(new Solution().shortestDistanceAfterQueries(5, [[2, 4], [0, 2], [0, 4]]).toString() === [3, 2, 1].toString())\r\nconsole.log(new Solution().shortestDistanceAfterQueries(4, [[0, 3], [0, 2]]).toString() === [1, 1].toString())\r\nconsole.log(new Solution().shortestDistanceAfterQueries(6, [[1, 4], [0, 2]]).toString() === [3, 3].toString())\r\nconsole.log(new Solution().shortestDistanceAfterQueries(500, [[0, 2], [2, 4], [4, 6], [6, 8], [8, 10], [10, 12], [12, 14], [14, 16], [16, 18], [18, 20], [20, 22], [22, 24], [24, 26], [26, 28], [28, 30], [30, 32], [32, 34], [34, 36], [36, 38], [38, 40], [40, 42], [42, 44], [44, 46], [46, 48], [48, 50], [50, 52], [52, 54], [54, 56], [56, 58], [58, 60], [60, 62], [62, 64], [64, 66], [66, 68], [68, 70], [70, 72], [72, 74], [74, 76], [76, 78], [78, 80], [80, 82], [82, 84], [84, 86], [86, 88], [88, 90], [90, 92], [92, 94], [94, 96], [96, 98], [98, 100], [